let loggerBinding: RuntimeLoggerProviderBinding | undefined;
afterEach(() => loggerBinding?.unbind());

// Real skill file contents provided by the user, base64-encoded to avoid escaping issues
const ZMX_SKILL_B64 =
  '';
const QUERY_SKILL_B64 =
  '';

function decodeB64(b64: string): string {
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(b64, 'base64').toString('utf-8');
  }
  // Fallback for environments without Buffer
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new TextDecoder('utf-8').decode(bytes);
}

const ZMX_SKILL_CONTENT = decodeB64(ZMX_SKILL_B64);
const QUERY_SKILL_CONTENT = decodeB64(QUERY_SKILL_B64);

describe('targeted skill routing - real skill body result contract', () => {
  it('directed pre-load carries the inline Skill body in the Capability result payload', async () => {
    loggerBinding = bindRuntimeLoggerProvider({ component: 'test' } as any);
    const skillsRoot = await mkdtemp(join(tmpdir(), 'nextagent-skill-discard-'));
    try {
      // Write real skill files exactly as provided by the user
      await mkdir(join(skillsRoot, 'cn-data-query'), { recursive: true });
      await writeFile(join(skillsRoot, 'cn-data-query', 'SKILL.md'), QUERY_SKILL_CONTENT, 'utf-8');
      await mkdir(join(skillsRoot, 'cn-data-zmx-query'), { recursive: true });
      await writeFile(join(skillsRoot, 'cn-data-zmx-query', 'SKILL.md'), ZMX_SKILL_CONTENT, 'utf-8');

      const harness = await makeHarness(skillsRoot);

      await harness.agent.execute(harness.run, harness.context, new AbortController().signal);

      // 1. Directed skill router invoked the REAL Skill tool with the correct target
      const directedCall = harness.invocationRequests.find(
        (req) => req.capabilityId === 'Skill' && typeof req.toolCallId === 'string' && req.toolCallId.startsWith('directed-skill:'),
      );
      expect(directedCall).toBeDefined();
      expect(directedCall?.arguments).toEqual({ name: 'cn-data-zmx-query' });

      // 2. The REAL skill-tool carries the REAL body in the same result payload.
      const directedResult = harness.invocationResults[harness.invocationRequests.indexOf(directedCall!)!];
      expect(directedResult?.status).toBe('SUCCEEDED');
      expect(directedResult?.structuredPayload).toMatchObject({
        name: 'cn-data-zmx-query',
        status: 'loaded',
      });
      expect(directedResult?.generatedMessages).toEqual([]);
      const body = String(directedResult?.structuredPayload?.['body'] ?? '');
      expect(body).toContain('<skill_content name="cn-data-zmx-query">');
      // The zmx skill body uses Python scripts
      expect(body).toContain('python $CQ');
      expect(body).toContain('cn-data-zmx-query');
      // The zmx body is the Python version, not the curl version
      expect(body).toContain('Agent 推理 + Python 脚本');

      // 3. The directed pre-load is persisted as one CAPABILITY_RESULT message.
      // The raw body is model-facing payload content and is not projected as a
      // page-visible conversation message.
      const capabilityResultMessages = harness.appendedMessages.filter((msg) => msg.draft.role === 'CAPABILITY_RESULT');
      expect(capabilityResultMessages.length).toBeGreaterThanOrEqual(1);
      const skillResultContent = capabilityResultMessages.map((msg) => msg.draft.content).join('');
      expect(skillResultContent).toContain('cn-data-zmx-query');
      expect(skillResultContent).toContain('python $CQ');

      // 4. The legacy page-hidden USER Skill body message is not created.
      const skillBodyMessages = harness.appendedMessages.filter((msg) => msg.draft.role === 'USER' && msg.draft.visible === false);
      expect(skillBodyMessages).toEqual([]);
    } finally {
      await rm(skillsRoot, { recursive: true, force: true });
    }
  });
});

async function makeHarness(skillsRoot: string) {
  const run = makeRun();
  const context: RequestContext = {
    requestContextId: brand<string, 'RequestContextId'>('ctx-discard-repro'),
    sessionId: run.sessionId,
    requestId: run.requestId,
    runId: run.runId,
    agentTurnIndex: 0,
    identityContext: {
      tenantId: brand<string, 'TenantId'>('tenant-discard-repro'),
      subjectId: brand<string, 'SubjectId'>('subject-discard-repro'),
      displayName: 'Discard Repro',
    },
    locale: brand<string, 'RequestLocale'>('zh-CN'),
    routingConstraints: {
      targetSkill: 'cn-data-zmx-query',
    },
    agentId: run.agentId,
    agentVersion: run.agentVersion,
    agentAssemblyRef: run.agentAssemblyRef,
    nextLifecycleStage: 'BEFORE_MODEL_INVOKE',
    toolCallStates: [],
    flowVariables: {},
  };
  const assembly = makeAssembly(run.agentId, run.agentVersion);

  // --- REAL skill discovery from real files on disk ---
  const skillDiscovery = createSystemLocalSkillDiscoveryForTesting({ systemSkillsRoot: skillsRoot });

  // --- REAL tool catalog with real Skill tool ---
  const workspaceFiles = fakeWorkspaceFiles();
  const skillSourceRegistry: SkillSourceRegistry = {
    resolveSkillSource(providerId) {
      return providerId === localSkillsSystemProvider.providerId ? skillDiscovery : undefined;
    },
  };
  const toolCatalog = createToolCatalog({
    provider: builtinToolsProvider,
    tools: [skillToolDefinition],
    dependencies: { skillSources: skillSourceRegistry, workspaceFiles },
  });

  // --- REAL capability catalog (skills + tools) ---
  const capabilityCatalog: CapabilityCatalog = new StaticCapabilityCatalog([], {
    eagerDiscoveries: [toolCatalog, skillDiscovery],
    skillSourceDiscoveries: [skillDiscovery as any],
  });

  // --- REAL governed invocation port with real executor ---
  const invocationRequests: CapabilityInvocationRequest[] = [];
  const invocationResults: CapabilityInvocationResult[] = [];
  const underlyingPort = new GovernedCapabilityInvocationPort(
    {
      async resolveForInvocation(capabilityId, signal) {
        const all = await capabilityCatalog.listAvailable({
          tenantId: context.identityContext.tenantId,
          subjectId: context.identityContext.subjectId,
          agentAssembly: assembly,
          includeUnavailable: false,
        });
        return all.find((d) => d.capabilityId === capabilityId);
      },
    },
    createStaticCapabilityExecutorFactory([{ provider: builtinToolsProvider, executor: new BuiltinToolsExecutor(toolCatalog) }]),
  );
  const capabilityInvocation: CapabilityInvocationPort = {
    async invoke(request, signal, runtimeContext) {
      invocationRequests.push(request);
      const result = await underlyingPort.invoke(request, signal, runtimeContext);
      invocationResults.push(result);
      return result;
    },
  };

  // --- Model mock: simulates real model behavior ---
  // Turn 1: model can't see pre-loaded skill body, so it independently picks
  //         cn-data-query (wrong) because the pre-loaded body was discarded.
  const modelRequests: ModelInvocationRequest[] = [];
  let modelRoundDone = false;
  const model: ModelInvocationService = {
    complete: vi.fn(async () => {
      throw new Error('not used');
    }),
    stream: vi.fn(
      modelEventStreamFixture(async function* (request: ModelInvocationRequest): AsyncIterable<ModelStreamDelta> {
        modelRequests.push(request);
        if (!modelRoundDone) {
          modelRoundDone = true;
          yield {
            content: '',
            finishReason: 'tool-calls',
            toolCalls: [{ toolCallId: 'tool-1', toolName: 'Skill', arguments: { name: 'cn-data-query' } }],
          } as ModelStreamDelta;
          return;
        }
        yield { content: 'done', finishReason: 'stop' } as ModelStreamDelta;
      }),
    ),
  };

  // --- Context engine: captures capabilityGeneratedMessages ---
  const contextRequests: ContextAssemblyRequest[] = [];
  const contextEngine: ContextEnginePort = {
    assemble: vi.fn(async (request: ContextAssemblyRequest) => {
      contextRequests.push(request);
      return makeContextAssembly(request);
    }),
    render: vi.fn(async (assembly: ContextAssembly) => ({
      requestContextId: assembly.request.requestContextId,
      messages: [],
      tools: [],
      modelConfiguration: {
        modelId: 'test-model',
        contextWindowTokens: 128_000,
        temperature: 0.55,
        maxOutputTokens: 512,
        topP: 1,
        toolChoice: 'AUTO' as const,
        defaultTimeoutMs: 30_000,
        defaultMaxRetries: 2,
      },
      modelOptions: { maxOutputTokens: 512 },
      providerOptions: {},
    })),
  };

  const assemblyRegistry: AgentAssemblyRegistry = {
    active: vi.fn(async () => assembly),
    require: vi.fn(async () => assembly),
  };
  const appendedMessages: Array<{
    readonly draft: {
      readonly role: string;
      readonly content: string;
      readonly visible?: boolean;
      readonly metadata?: Record<string, unknown> | undefined;
    };
  }> = [];
  const runState: AgentRunStatePort = {
    setCapabilityTerminalAnswer: vi.fn(async () => undefined),
    emitEvent: vi.fn(async () => undefined),
    appendMessage: vi.fn(async (_run, _ctx, draft) => {
      appendedMessages.push({
        draft: { role: draft.role, content: draft.content, visible: draft.visible, metadata: draft.metadata as Record<string, unknown> | undefined },
      });
      return brand<string, 'MessageId'>('msg-discard');
    }),
    appendGeneratedUserMessage: vi.fn(async (_run, _ctx, draft) => {
      appendedMessages.push({
        draft: { role: draft.role, content: draft.content, visible: draft.visible, metadata: draft.metadata as Record<string, unknown> | undefined },
      });
      return brand<string, 'MessageId'>('msg-skill-content');
    }),
    saveCheckpoint: vi.fn(async () => undefined),
    requestPendingInput: vi.fn(async () => {
      throw new Error('not used');
    }),
  };

  return {
    run,
    context,
    contextRequests,
    modelRequests,
    invocationRequests,
    invocationResults,
    appendedMessages,
    agent: new DefaultAgent({
      contextEngine,
      model,
      capabilityCatalog,
      capabilityInvocation,
      assemblyRegistry,
      runState,
    }),
  };
}

function makeRun(): RequestRun {
  return {
    runId: brand<string, 'RequestRunId'>('run-discard-repro'),
    sessionId: brand<string, 'SessionId'>('session-discard-repro'),
    requestId: brand<string, 'MessageId'>('request-discard-repro'),
    agentId: brand<string, 'AgentId'>('agent-discard-repro'),
    agentVersion: brand<string, 'AgentVersion'>('v1'),
    agentAssemblyRef: 'agent-discard-repro:v1',
    attempt: 1,
    status: 'EXECUTING',
    version: 1,
    terminalCommitState: 'NOT_STARTED',
    createdAt: brand<number, 'EpochMillis'>(1),
    updatedAt: brand<number, 'EpochMillis'>(1),
  };
}

function makeAssembly(agentId: RequestRun['agentId'], agentVersion: RequestRun['agentVersion']): AgentAssembly {
  return {
    agentId,
    agentType: brand<string, 'AgentType'>('default'),
    agentVersion,
    agentAssemblyRef: agentId + ':' + agentVersion,
    displayName: 'Discard Repro Agent',
    description: 'Test',
    workspacePolicy: { schemaVersion: '1', isolationMode: 'subject', roots: [] },
    modelIds: ['default'],
    capabilityBindings: [],
    userInvocable: true,
    agentInvocation: 'BOUND',
    runtimeSettings: { maxTurns: 3, maxToolCallsPerTurn: 30 },
  };
}

function makeContextAssembly(request: ContextAssemblyRequest): ContextAssembly {
  return {
    request,
    systemPrompt: { sections: [] },
    selectedMessageRefs: [],
    visibleCapabilities: [],
    modelConfiguration: {
      modelId: 'test-model',
      contextWindowTokens: 128_000,
      temperature: 0.55,
      maxOutputTokens: 512,
      topP: 1,
      toolChoice: 'AUTO' as const,
      defaultTimeoutMs: 30_000,
      defaultMaxRetries: 2,
    },
    modelOptions: { maxOutputTokens: 512 },
    modelSelectionReason: 'test',
  };
}

